#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
const int MAX_N = 2 * 100000 + 1;

long long modpow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    if (!(cin >> n >> m)) return 0;

    static long long fac[MAX_N + 1];
    static long long fac_inv[MAX_N + 1];

    fac[0] = 1;
    for (int i = 1; i <= MAX_N; ++i) {
        fac[i] = fac[i - 1] * i % MOD;
    }

    fac_inv[MAX_N] = modpow(fac[MAX_N], MOD - 2, MOD);
    for (int i = MAX_N; i >= 1; --i) {
        fac_inv[i - 1] = fac_inv[i] * i % MOD;
    }

    auto mod_nCr = [&](long long nn, long long r) -> long long {
        if (nn < r || nn < 0 || r < 0) return 0;
        long long tmp = fac_inv[nn - r] * fac_inv[r] % MOD;
        return tmp * fac[nn] % MOD;
    };

    long long ans;
    if (n - 3 > 0) {
        ans = mod_nCr(m, n - 1) * (n - 2) % MOD * modpow(2, n - 3, MOD) % MOD;
    } else {
        ans = mod_nCr(m, n - 1) * (n - 2) % MOD;
    }
    ans %= MOD;
    cout << ans << '\n';

    return 0;
}

